import os,zipfile
LOGO='<svg width="62" height="44" viewBox="0 0 70 44" aria-hidden="true" fill="none" stroke-linecap="round"><path d="M31 14A14 14 0 1 0 31 30V22H21" stroke="#3a3a3c" stroke-width="5.5"/><path d="M61 13A15 15 0 1 0 61 31" stroke="#a08f2a" stroke-width="5.5"/><path d="M22 8H55M38 8V37" stroke="#fff" stroke-width="10"/><path d="M22 8H55M38 8V37" stroke="#c4161c" stroke-width="5.5"/></svg>'
SV=[("human-capital","Human Capital","👥","Talent acquisition and manpower outsourcing that unite candidate talent with the right opportunity.",["Talent Acquisition","Manpower Outsourcing"],"GTC stands out by bringing the best people together in the best way they can. We aim to be the company of choice for clients, job seekers and employers, with honesty, integrity and quality placements."),
("catering","Catering Services","🍽️","The first industrial caterer registered with the Kuwait Chamber of Commerce, since 1959.",["Hospital Catering","Military & Police Catering","Remote Camp Site Catering","Schools & Universities Catering"],"GTC serves teams from hundreds to thousands, supplying over 50,000 meals daily to schools, universities, hospitals, armed forces, fire and police stations, remote camps and industrial sites."),
("general-services","General Services","🛠️","Facility management and supply chain, run to a customised programme.",["Housekeeping & Laundry","General Maintenance","Pest Control","Gardening & Landscaping","Camp Management","HVAC & Water Supply","Accommodation","Transportation","Logistics & Warehousing"],"GTC provides high-quality management and maintenance for buildings, camps and their facilities, with cleaning programmes tailored to each customer."),
("security-service","Security Service","🛡️","Trained security officers protecting sites, camps and facilities.",["Site Security","Camp Security"],"Professional security services delivered with the same ethical approach GTC applies everywhere: getting it right the first time."),
("industrial-service","Industrial Service","🏗️","Construction, mechanical and electrical contracting.",["Construction & Contracting","Mechanical & Electrical Contracting"],"Civil, mechanical and electromechanical works for government, oil and private-sector clients across Kuwait and the GCC."),
("partnership","International & Local Partnership","🤝","Agency facilitation, sponsorship and franchise retail branding.",["Sponsorship & Agency Facilitation","Franchise Retail Branding"],"GTC helps international brands and local partners enter and grow in Kuwait through agency facilitation and franchise retail branding.")]
ROLES="A/B Seaman|Accountant|Administrative Assistant|Architect|Agriculturist|Auto Technician|Boat Mechanic|Camp Supervisor|Chemical Engineer|Chemist|Civil Engineer|Clerk|Customer Service Officer|Diesel Mechanic|Electrician|Electrical Engineer|Finance Manager|Heavy Duty Driver|Heavy Equipment Operator|HSE Engineer|Industrial Engineer|Information Technologist (I.T)|Laundry Supervisor|Lawyer|Maintenance Fitter|Marketing Officer|Mechanical Engineer|Nurse|Operations Coordinator|Orderly|Painter|Pharmacist|Procurement Officer|Public Relations Officer|Quality Control Officer|Safety Officer|Sales Associate|Security Officer|Teacher|Translator|Welder".split("|")
CAT={"Engineering":"Engineer|Architect|Chemist|Electrician|Fitter|Welder|Painter|Mechanic|Technician|Operator|Industrial","Corporate":"Accountant|Administrative|Clerk|Finance|Lawyer|Marketing|Procurement|Public|Sales|Translator|Information|Customer|Operations","Field & Care":"Seaman|Camp|Driver|Laundry|Nurse|Orderly|Pharmacist|Safety|Security|Teacher|Agriculturist|Quality"}
def cat(r):
 for k,v in CAT.items():
  if any(w in r for w in v.split("|")):return k
 return "Corporate"
def nav(cur):
 a=lambda h,t:f'<a href="{h}"{" aria-current=page" if cur==h else ""}>{t}</a>'
 ab=[("about.html","Company profile"),("chairman.html","Chairman’s message"),("strategy.html","Strategic objectives"),("quality.html","Quality & certificates"),("csr.html","Social responsibility"),("news.html","News & events")]
 return '<nav id="nav">'+a("index.html","Home")+'<details><summary>About</summary><div class="dd">'+"".join(a(h,t) for h,t in ab)+'</div></details><details><summary>Services</summary><div class="dd">'+"".join(a(f"{s[0]}.html",s[1]) for s in SV)+'</div></details>'+a("careers.html","Careers")+a("contact.html","Contact")+'<a class="cta" href="careers.html">Join GTC</a></nav>'
def page(f,title,body,hero=None):
 h=hero or f'<div class="page"><div class="wrap reveal"><div class="crumb"><a href="index.html">Home</a> / {title}</div><h1>{title}</h1></div></div>'
 ft='<footer><div class="wrap"><div class="grid"><div><div class="logo">'+LOGO+'<div><b>General Trading Company</b><small>W.L.L</small></div></div><p style="margin-top:14px;max-width:34ch">Serving Kuwait and the GCC since 1959. Trust, Talent, Innovation and Passion.</p></div><div><h4>Company</h4><a href="about.html">Profile</a><a href="chairman.html">Chairman</a><a href="quality.html">Quality</a><a href="news.html">News</a></div><div><h4>Services</h4>'+"".join(f'<a href="{s[0]}.html">{s[1]}</a>' for s in SV[:4])+'</div><div><h4>Contact</h4><a href="contact.html">Dasman Complex, Block 2A, Sharq</a><a href="tel:+96522425101">+965 2242 5101</a><a href="mailto:info@gtckuwait.com">info@gtckuwait.com</a></div></div><p style="margin-top:34px;opacity:.6;font-size:13px">© GTC. Concept redesign prepared as a demo; not the official website.</p></div></footer>'
 open(f,"w").write(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | GTC Kuwait</title><meta name="description" content="General Trading Company (GTC), Kuwait: catering, human capital, facility management, security and industrial services since 1959."><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@600;700&family=Bricolage+Grotesque:wght@600;700&family=Hanken+Grotesk:wght@400;600&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/style.css"></head><body><div class="demo">Demo concept for GTC: a redesign proposal, not the live website.</div><header><div class="wrap bar"><a class="logo" href="index.html">{LOGO}<div><b>General Trading Company</b><small>W.L.L</small></div></a><button class="burger" aria-label="Menu" aria-expanded="false">Menu</button>{nav(f)}</div></header>{h}{body}{ft}<script src="assets/app.js"></script></body></html>')
cards="".join(f'<a class="card" href="{s[0]}.html"><div class="ico">{s[2]}</div><h3>{s[1]}</h3><p>{s[3]}</p></a>' for s in SV)
home=f'''<section><div class="wrap"><h2>Six services. One accountable partner.</h2><p class="lead">From daily meals to site security, one team, one standard.</p><div class="grid">{cards}</div></div></section>
<section class="stats"><div class="wrap grid"><div><strong>62</strong>years serving Kuwait</div><div><strong>38</strong>services</div><div><strong>559</strong>projects</div><div><strong>4,997</strong>team members</div></div></section>
<section style="padding:0"><div class="band"><div class="wrap"><p>Corporate ideals, ethical values and a continuing emphasis on partnership</p><a class="btn" href="careers.html">Search jobs</a></div></div></section><section><div class="wrap"><h2>Our clients</h2><p class="lead">Anchored in Kuwait, GTC operates and has investments in the Arabian Gulf and Levant.</p><div class="chips"><span class="chip">Kuwait Government</span><span class="chip">Oil companies</span><span class="chip">Armed forces</span><span class="chip">Hospitals</span><span class="chip">Schools & universities</span><span class="chip">Private sector</span></div></div></section><section><div class="wrap two"><div class="prose"><h2>Getting it right the first time</h2><p>GTC is an approved contractor for the Kuwait government, oil companies, the US Army and private-sector clients across the GCC. We ask, we listen and we respond to the needs of our clients and our team.</p><a class="btn" href="about.html">Read our story</a></div><div class="pitch"><h3>Why this redesign</h3><p>Faster pages, a working careers search, mobile navigation, accessible colours and a clear contact path. A short note on the problems it solves is in the README.</p></div></div></section>'''
hero='<div class="hero"><div class="wrap reveal"><h1>We shape the future</h1><p>Transforming challenge to success through trust, talent, innovation and passion. Kuwait’s trusted services partner since 1959.</p><a class="btn" href="services.html">Explore services</a><a class="btn ghost" href="contact.html">Talk to us</a><div class="meals"><strong id="meals">50,000</strong><span>meals served every day</span></div></div></div>'
page("index.html","Home",home,hero)
prose=lambda t:f'<section><div class="wrap prose">{t}</div></section>'
page("about.html","Company profile",prose("<p>General Trading Company (GTC) was established in 1959 and has grown into one of Kuwait’s leading companies in restaurant and catering, recruitment, facilities management, healthcare, training, civil works and electromechanical works.</p><p>With over 4,000 staff, GTC delivers contracts awarded by Kuwaiti public authorities, oil companies, the US Army and private companies in Kuwait and the GCC.</p><p>Our service is built on an ethical approach: total solutions, delivered right the first time, with a direct line of communication to every client.</p>"))
page("chairman.html","Chairman’s message",prose("<p>Placeholder: the chairman’s message goes here. This demo keeps the page and structure from the current site, ready for the official text and portrait.</p>"))
page("strategy.html","Strategic objectives",f'<section><div class="wrap"><p class="lead" style="font-size:22px">To be a world class service provider that helps consumers and businesses achieve their target.</p><div class="grid"><div class="card"><h3>Tactical growth</h3></div><div class="card"><h3>Quality service</h3></div><div class="card"><h3>Ethical development</h3></div></div></div></section>')
page("quality.html","Quality & certificates",prose("<p>Placeholder: certificate gallery. Each certificate becomes a card with issuer, scope and expiry date, with a downloadable PDF.</p>"))
page("csr.html","Social responsibility",f'<section><div class="wrap"><div class="grid"><div class="card"><h3>Health, safety & environment</h3><p>Our commitments on site and in camps.</p></div><div class="card"><h3>Training & education</h3><p>Developing our people and communities.</p></div></div></div></section>')
page("news.html","News & events",prose("<p>Placeholder: a single feed combining news and events, filterable and dated. The current site splits these across several pages and has not been updated for years.</p>"))
page("services.html","Services",f'<section><div class="wrap"><div class="grid">{cards}</div></div></section>')
for s in SV:
 subs="".join(f'<li>{x}</li>' for x in s[4])
 page(f"{s[0]}.html",s[1],f'<section><div class="wrap two"><div class="prose"><p>{s[5]}</p><h3>What we offer</h3><ul>{subs}</ul><p style="margin-top:20px"><a class="btn" href="contact.html">Request a quote</a></p></div><div class="side">'+"".join(f'<a href="{t[0]}.html">{t[1]}</a>' for t in SV if t!=s)+'</div></div></section>')
chips='<button class="chip" data-c="all" aria-pressed="true">All</button>'+"".join(f'<button class="chip" data-c="{k}" aria-pressed="false">{k}</button>' for k in CAT)
jobs="".join(f'<div class="job" data-c="{cat(r)}" data-t="{r.lower()}"><div><b>{r}</b><br><span>{cat(r)} · Kuwait</span></div><a class="btn" href="mailto:info@gtckuwait.com?subject=Application: {r}">Apply</a></div>' for r in ROLES)
page("careers.html","Careers",f'<section><div class="wrap"><p class="lead">Search roles by title or filter by area. The live site currently shows a raw plugin tag where this list should be.</p><input id="q" type="search" placeholder="Search roles, e.g. Civil Engineer" aria-label="Search roles"><div class="chips">{chips}</div><p id="count" style="margin-bottom:12px"></p>{jobs}</div></section>')
page("contact.html","Contact",'<section><div class="wrap two"><form id="cf"><input name="n" placeholder="Your name" required><input name="e" type="email" placeholder="Email" required><select name="s"><option>General enquiry</option><option>Service quote</option><option>Careers</option></select><textarea name="m" rows="6" placeholder="How can we help?" required></textarea><button class="btn">Send message</button></form><div class="card"><h3>GTC head office</h3><p><a href="https://www.google.com/maps/search/?api=1&query=Dasman+Complex+Sharq+Kuwait">Open in Google Maps</a></p><p>Sharq, Jaber Al-Mubarak Str., Dasman Complex, Block 2A, 2nd Floor, Kuwait<br><br>+965 2242 5101 / 5105<br>Fax +965 2242 1027<br>info@gtckuwait.com</p></div></div></section>')
open("README.md","w").write("# GTC Kuwait: demo redesign\nOpen index.html. Static HTML/CSS/JS, no build needed. Regenerate with `python3 build.py`.\n\nColours (charcoal, red, olive-gold) are sampled from screenshots of the live site and live in :root of assets/style.css. Confirm against GTC's official brand files before real use.\n\n## Problems on the current site this addresses\n- Careers page shows a raw `[wpjb_jobs_list]` shortcode instead of a job list\n- Pages last edited 2016-2021; footer says 2023\n- Events and news split across several pages\n- Google Maps error dialog on the Contact page\n- Stats block wraps awkwardly on phones; Clients section is empty\n- No search, filtering or mobile-first navigation\n")
z=zipfile.ZipFile("../gtc-kuwait-demo.zip","w",zipfile.ZIP_DEFLATED)
for r,_,fs in os.walk("."):
 for f in fs:
  if f!="build.py" or True:z.write(os.path.join(r,f))
z.close();print(sorted(os.listdir(".")))
